#!/usr/bin/env python3
"""Round-58 residual handoff r1: 8 reviewer/critic seats attacking the committed build (c1e39ef3) before T0.
Below the v1/v2 validator bands by design (prompt §6 item 2: residual checks go into one call of <= 8 reviewer/critic seats);
the taskCall is built in the same shape as the validator's (context + tasks[name, agent, task]) and written as r1-dispatch.json."""
import importlib.util, json, os
HERE = os.path.dirname(os.path.abspath(__file__))
spec = importlib.util.spec_from_file_location("w1spec", os.path.join(HERE, "make_spec_w1.py"))
w1 = importlib.util.module_from_spec(spec); spec.loader.exec_module(w1)
BUILD = "c1e39ef3567542b2dc602cc235ed717d6dfbd915"
L, W, SCR = w1.LANE, w1.W, w1.SCR
R = f"{W}/r1"
ctx = w1.CONTEXT.replace("Round-58 kake wave w1 (one v2 wave: build + attack items together).",
                         f"Round-58 kake residual handoff r1 (8 reviewer/critic seats; attack the committed build {BUILD} before the claims are measured).")
ctx = ctx.replace(".ufo/waves/round-58/w1/<Seat>.md", ".ufo/waves/round-58/r1/<Seat>.md").replace(".ufo/waves/round-58/w1/<Seat>.files/", ".ufo/waves/round-58/r1/<Seat>.files/")
ctx += (f" Counters are version 2 (contract.md § Counter versions; frozen at 1c0aa211). The build under attack is lane commit {BUILD}; wave-1 reports are in "
        f"{W}/w1/. Never edit lane files: findings only.")
items = [
 ("ReviewerEntryIdentification", "reviewer", f"Sentence-level fidelity review of {L}/corpus/knowledge/baidu-spider-identification.md (at {BUILD}) against the retained page {W}/sources/S423.html (`python3 -B {W}/span_tools.py window S423`). Use the reference translation {W}/w1/ReviewerEntryFidelityPrep.md and the must-not list {W}/w1/CriticEntryOverreach.md. For every rendering and every prose claim: supported / overreach / dropped qualifier / wrong (with the page text). Also check the UA-channel token sentence and the cross-links (files exist). Report sections: `FINDINGS:` (line, entry text, page text, fix), `CLEAN LINES:` (count), `VERDICT:`."),
 ("ReviewerEntryUnblocking", "reviewer", f"Sentence-level fidelity review of {L}/corpus/knowledge/baidu-spider-unblocking.md (at {BUILD}) against {W}/sources/S424.html (`python3 -B {W}/span_tools.py window S424`), using {W}/w1/ReviewerEntryFidelityPrep.md (S424 reference) and {W}/w1/CriticEntryOverreach.md. Check every rendering, the sweep counts it states (re-run them on the retained body), the curl command text against the page, and every cross-link claim (e.g. baidu-friendly-crawl-guidance.md binding PC and mobile). Report sections: `FINDINGS:` (line, entry text, page text, fix), `SWEEPS RE-RUN:`, `VERDICT:`."),
 ("CriticLedgerNotes", "critic", f"Attack the truth of the C1 ledger notes: {L}/.ufo/waves/round-58/receipt-rewrites.json (19 events). For at least 10 events, check the note's factual statements against `git -C {L} show <commit> -- <path>`, the commit message, and the pointer it names (LOG.md line numbers, settlement files, errata). Is any note false, or does any note claim a re-run/relabel the evidence does not support? Also check that the six events {L}/.ufo/waves/round-57/receipt-errata.json lists appear with the same commits/blobs. Report sections: `CHECKED:` (event, note claim, evidence, true/false), `FALSE NOTES:`, `VERDICT:`."),
 ("ReviewerLessonGate", "reviewer", f"Review {L}/corpus/lessons/round-58.md at {BUILD} for number and pointer drift: every count (rows 160->162, collisions 8, staged 129, quarantine 12, 19 events, 13/11/12 disclosure counts), every file pointer (exists at {BUILD}?), every commit hash (resolves?), the two Gate lines (anchor equals the registry row anchor in {L}/corpus/SOURCES.md; quote a raw page-unique substring; sha256/bytes equal sources/receipts.json), and the S378 reject reason (re-open the page with curl and grep the quoted sentence). Report sections: `FINDINGS:` (line, claim, observed, fix), `VERIFIED:`, `VERDICT:`."),
 ("CriticC1V2Cheat", "critic", f"Re-attack the version-2 C1 counter {W}/c58_receipt_rewrites.py: in a shared clone of the lane at {BUILD} under {SCR}/CriticC1V2Cheat (selftest identity), try to reach met=True without a true disclosure (rename-with-edit, subdir relocation, symlink, pointer-only note, a kind the classifier assigns that misnames, a merge second-parent rewrite, rewriting a receipt outside control(s)/). Version 1's cheats are in {W}/w1/CriticC1Cheat.md: say which v2 closes and which remain. You need dummy `.ufo/waves/round-58/controls/after-c2-x.txt` and `after-c3-x.txt` files to satisfy new_receipts. Report sections: `CHEATS:` (cheat, v2 result, closed?), `REMAINING LIMITS:`, `VERDICT:`."),
 ("CriticC2V2Cheat", "critic", f"Re-attack the version-2 C2 gate {W}/c58_resolver_cases.py (14 cases, per-run random fixture ids, random case dirs): write minimal WRONG tools (id masks, canned output, partial fixes, a tool that reads the gate's expected regexes) and score them in a shared clone at {BUILD} under {SCR}/CriticC2V2Cheat (commit the stub as scripts/id_resolver.py, selftest identity; run with --work in your scratch, at least 3 seeds). Version 1's cheats: {W}/w1/CriticC2Cheat.md. Report sections: `CHEATS:` (stub, tallies per seed, met?), `HOLES:`, `VERDICT:`."),
 ("ReviewerResolverDiff", "reviewer", f"Code-review the landed tool change: `git -C {L} diff 044048597d62f3199494b63b36e90dd57825e350 {BUILD} -- scripts/id_resolver.py`. Check the fence state machine against CommonMark (opening 0-3 spaces, >= 3 backticks or tildes, backtick info string without backticks, closing same char >= length, only whitespace after, EOF), the `-z` path parse (decode errors, empty chunks), that working-tree mode is unchanged, the new selftest cases (do they fail on the base tool?), and that the source names neither `c57_idresolver_gate` nor `.ufo/` nor `reference(` (the round-57 gate's G2 rejects those). Run its selftest from a scratch copy. Report sections: `FINDINGS:` (severity, line, input, fix), `SELFTEST:`, `VERDICT:`."),
 ("ReviewerNoHarm", "reviewer", f"No-harm check of the build {BUILD} against earlier lane gates. In a shared clone at {BUILD} under {SCR}/ReviewerNoHarm run: .ufo/waves/round-55/c55_readme_index.py, .ufo/waves/round-57/c57_receipt_pins.py, .ufo/waves/round-57/c57_idresolver_gate.py (--fleet /home/vgpnk/Projects/shokunin), .ufo/waves/round-52/c52_wave_ledger.py, .ufo/waves/round-57/c57_quote_truth.py and .ufo/waves/round-56/c56_selftally.py (slow, ~2 min) — each with `--root <clone> --revision {BUILD}` (read each counter's --help/docstring for exact flags). Compare with the base results in {W}/w1/ExecHistoricalGates.md. A gate green at the base and red at {BUILD} is a harm unless the SKILL.md row now marks it historical by design (c57_quote_truth is so marked: say whether its red is exactly the mirror-row condition). Report sections: `RUNS:` (gate, base result, build result), `NEW REDS:`, `VERDICT:`."),
]
tasks = []
for name, agent, text in items:
    tasks.append({"name": name, "agent": agent,
                  "task": w1.GODSPEED + text + f"\n\nLane bounds: leaf member — no subagent dispatch.\n\nReport: write your scoped findings to .ufo/waves/round-58/r1/{name}.md"})
out = {"schema": "kake-r58-residual-dispatch-v1", "wave": "r1", "policy": "residual (<= 8 reviewer/critic seats; prompt §6 item 2)",
       "counts": {"spawn": len(tasks), "resume": 0, "total": len(tasks)}, "taskCall": {"context": ctx, "tasks": tasks}}
json.dump(out, open(os.path.join(HERE, "r1-dispatch.json"), "w"), indent=1, ensure_ascii=False)
print(len(tasks))
